begin;

create function life_private.operation_schedule_row_v2(r jsonb) returns jsonb language plpgsql immutable set search_path='' as $$
declare raw text:=coalesce(r->>'date',''); date_parts text[]; time_parts text[]; next_date text:=raw; start_time text:=coalesce(r->>'startTime',''); end_time text:=coalesce(r->>'endTime',''); next_row jsonb; candidate_date text;begin
 date_parts:=regexp_match(raw,'([0-9]{4})[./-][[:space:]]*([0-9]{1,2})[./-][[:space:]]*([0-9]{1,2})');
 if date_parts is not null then
  candidate_date:=date_parts[1]||'-'||lpad(date_parts[2],2,'0')||'-'||lpad(date_parts[3],2,'0');
  begin perform candidate_date::date; next_date:=candidate_date; exception when others then next_date:=raw; end;
 end if;
 time_parts:=regexp_match(raw,'([0-9]{1,2}):([0-9]{2})[[:space:]]*[~～-][[:space:]]*([0-9]{1,2}):([0-9]{2})');
 if time_parts is not null and time_parts[1]::integer between 0 and 23 and time_parts[2]::integer between 0 and 59 and time_parts[3]::integer between 0 and 23 and time_parts[4]::integer between 0 and 59 then
  if start_time='' then start_time:=lpad(time_parts[1],2,'0')||':'||time_parts[2]; end if;
  if end_time='' then end_time:=lpad(time_parts[3],2,'0')||':'||time_parts[4]; end if;
 end if;
 next_row:=jsonb_build_object('date',next_date,'startTime',start_time,'endTime',end_time,'topic',coalesce(r->>'topic',''),'instructor',coalesce(r->>'instructor',''),'hours',coalesce(r->>'hours',''),'assistant',coalesce(r->>'assistant',''),'assistantHours',coalesce(r->>'assistantHours',''),'location',coalesce(r->>'location',''));
 if r ? 'mode' then next_row:=next_row||jsonb_build_object('mode',coalesce(r->>'mode',''),'holiday',coalesce(r->>'holiday','')); end if;
 return next_row;
end$$;

update public.life_operation_documents d
set content=jsonb_set(d.content,'{tables,schedule}',coalesce((select jsonb_agg(life_private.operation_schedule_row_v2(row.value) order by row.ordinality) from jsonb_array_elements(d.content#>'{tables,schedule}') with ordinality row(value,ordinality)),'[]'::jsonb)),revision=d.revision+1,updated_at=now()
where exists(select 1 from jsonb_array_elements(d.content#>'{tables,schedule}') row where not row ?& array['startTime','endTime']);

create or replace function life_private.operation_schema(k text) returns jsonb language sql immutable set search_path='' as $fn$select $schema${"plan":{"fields":[{"key":"title","label":"과정명","type":"text","required":true,"max":500},{"key":"year","label":"학년도","type":"number","required":true,"max":12},{"key":"academy","label":"영역 / 아카데미","type":"text","required":true,"max":500},{"key":"program","label":"세부프로그램명","type":"text","required":true,"max":500},{"key":"professor","label":"담당 교수 / 책임강사","type":"text","required":true,"max":500},{"key":"documentDate","label":"작성일","type":"date","required":true,"max":500},{"key":"startsOn","label":"교육 시작일","type":"date","required":true,"max":500},{"key":"endsOn","label":"교육 종료일","type":"date","required":true,"max":500},{"key":"audience","label":"주요대상 (성인학습자 / 지역주민)","type":"text","required":true,"max":500},{"key":"content","label":"1-2. 주요내용","type":"long","required":true,"max":5000},{"key":"method","label":"1-3. 교육방법","type":"long","required":true,"max":5000},{"key":"effects","label":"1-4. 기대효과","type":"long","required":true,"max":5000},{"key":"capacity","label":"가. 모집인원","type":"number","required":true,"max":12},{"key":"purposes","label":"다. 주요목적 (자격증 / 취창업 / 취미·여가 / 자기계발 / 진로진학 / 기타)","type":"text","required":true,"max":500},{"key":"partner","label":"거버넌스 기관명","type":"text","required":true,"max":500},{"key":"partnerField","label":"거버넌스 기관 분야","type":"text","required":true,"max":500},{"key":"partnerDevelopment","label":"교육과정개발 연계","type":"long","required":true,"max":5000},{"key":"partnerEmployment","label":"취·창업 연계","type":"long","required":true,"max":5000},{"key":"partnerInternship","label":"인턴십 연계","type":"long","required":true,"max":5000},{"key":"partnerService","label":"봉사 및 기여활동","type":"long","required":true,"max":5000},{"key":"partnerFollowUp","label":"교육종료 후 활성화 방안","type":"long","required":true,"max":5000},{"key":"qualificationNote","label":"자격증 과정 해당 여부 / 비해당 사유","type":"text","required":true,"max":500},{"key":"issuerInfo","label":"민간자격 발급기관 정보 (기관명·대표자·연락처·이메일·소재지·홈페이지)","type":"long","required":false,"max":5000},{"key":"refundPolicy","label":"민간자격 환불규정","type":"long","required":false,"max":5000},{"key":"staffNote","label":"보조강사·보조인력 해당 여부 및 비고","type":"long","required":true,"max":5000}],"tables":[{"key":"recruitment","label":"나. 주요대상","columns":[{"key":"category","label":"구분","type":"text","required":false,"max":500},{"key":"count","label":"인원","type":"number","required":false,"max":12},{"key":"ratio","label":"비율 (%)","type":"number","required":false,"max":12}],"min":1,"max":9},{"key":"national","label":"가. 국가자격증","columns":[{"key":"name","label":"자격명 (자격종류)","type":"text","required":false,"max":500},{"key":"issuer","label":"발급기관명 (홈페이지)","type":"text","required":false,"max":500},{"key":"exam","label":"시험일정","type":"text","required":false,"max":500},{"key":"cost","label":"응시료·자격발급비","type":"text","required":false,"max":500},{"key":"refund","label":"자격발급 환불규정","type":"text","required":false,"max":500},{"key":"contact","label":"연락처","type":"text","required":false,"max":500}],"min":0,"max":10},{"key":"private","label":"나. 민간자격증","columns":[{"key":"name","label":"자격명","type":"text","required":false,"max":500},{"key":"kind","label":"자격의 종류","type":"text","required":false,"max":500},{"key":"registration","label":"등록번호","type":"text","required":false,"max":500},{"key":"issuer","label":"자격발급기관","type":"text","required":false,"max":500},{"key":"cost","label":"총비용 및 세부내역","type":"text","required":false,"max":500}],"min":0,"max":10},{"key":"schedule","label":"회차별 강의계획","columns":[{"key":"date","label":"일자","type":"date","required":false,"max":500},{"key":"startTime","label":"시작시간","type":"time","required":false,"max":500},{"key":"endTime","label":"종료시간","type":"time","required":false,"max":500},{"key":"topic","label":"강의주제 및 내용","type":"text","required":false,"max":500},{"key":"instructor","label":"주강사명","type":"text","required":false,"max":500},{"key":"hours","label":"주강사 교육시간","type":"number","required":false,"max":12},{"key":"assistant","label":"보조강사명","type":"text","required":false,"max":500},{"key":"assistantHours","label":"보조강사 교육시간","type":"number","required":false,"max":12},{"key":"location","label":"교육장소","type":"text","required":false,"max":500},{"key":"mode","label":"수업방식","type":"text","required":false,"max":500},{"key":"holiday","label":"공휴일 수업여부 / 보강 날짜","type":"text","required":false,"max":500}],"min":1,"max":60},{"key":"instructors","label":"6. 강사현황","columns":[{"key":"affiliation","label":"소속","type":"text","required":false,"max":500},{"key":"position","label":"직위","type":"text","required":false,"max":500},{"key":"name","label":"성명","type":"text","required":false,"max":500},{"key":"theory","label":"이론 시수","type":"number","required":false,"max":12},{"key":"practice","label":"실습 시수","type":"number","required":false,"max":12}],"min":1,"max":60},{"key":"assistants","label":"7. 보조강사현황","columns":[{"key":"affiliation","label":"소속","type":"text","required":false,"max":500},{"key":"position","label":"직위","type":"text","required":false,"max":500},{"key":"name","label":"성명","type":"text","required":false,"max":500},{"key":"hours","label":"근무시수","type":"number","required":false,"max":12},{"key":"note","label":"비고","type":"text","required":false,"max":500}],"min":0,"max":60},{"key":"support","label":"8. 보조인력 현황","columns":[{"key":"department","label":"학과","type":"text","required":false,"max":500},{"key":"studentId","label":"학번","type":"text","required":false,"max":500},{"key":"name","label":"성명","type":"text","required":false,"max":500},{"key":"hours","label":"근무시수","type":"number","required":false,"max":12},{"key":"note","label":"비고","type":"text","required":false,"max":500}],"min":0,"max":60}]},"result":{"fields":[{"key":"title","label":"과정명","type":"text","required":true,"max":500},{"key":"year","label":"학년도","type":"number","required":true,"max":12},{"key":"academy","label":"영역 / 아카데미","type":"text","required":true,"max":500},{"key":"program","label":"세부프로그램명","type":"text","required":true,"max":500},{"key":"professor","label":"담당 교수 / 책임강사","type":"text","required":true,"max":500},{"key":"documentDate","label":"작성일","type":"date","required":true,"max":500},{"key":"startsOn","label":"교육 시작일","type":"date","required":true,"max":500},{"key":"endsOn","label":"교육 종료일","type":"date","required":true,"max":500},{"key":"content","label":"2. 주요내용","type":"long","required":true,"max":5000},{"key":"capacity","label":"모집정원","type":"number","required":true,"max":12},{"key":"enrolled","label":"모집인원","type":"number","required":true,"max":12},{"key":"completed","label":"수료인원","type":"number","required":true,"max":12},{"key":"certificates","label":"자격증 취득 수","type":"number","required":true,"max":12},{"key":"employed","label":"취창업인원","type":"number","required":true,"max":12},{"key":"surveyResponses","label":"이수자 교육만족 응답수","type":"number","required":true,"max":12},{"key":"satisfaction","label":"교육만족도율 (%)","type":"number","required":true,"max":12},{"key":"photoNote","label":"운영사진 설명 / 미첨부 사유","type":"long","required":true,"max":5000},{"key":"method","label":"교육방법","type":"long","required":true,"max":5000},{"key":"education","label":"교육내용","type":"long","required":true,"max":5000},{"key":"promotion","label":"교육생 모집 홍보","type":"long","required":true,"max":5000},{"key":"other","label":"기타","type":"long","required":true,"max":5000},{"key":"strengths","label":"우수한 점","type":"long","required":true,"max":5000},{"key":"strengthsNote","label":"우수한 점 비고","type":"text","required":false,"max":500},{"key":"improvements","label":"개선할 점","type":"long","required":true,"max":5000},{"key":"improvementsNote","label":"개선할 점 비고","type":"text","required":false,"max":500},{"key":"followUp","label":"환류 계획","type":"long","required":true,"max":5000},{"key":"followUpNote","label":"환류 계획 비고","type":"text","required":false,"max":500}],"tables":[{"key":"schedule","label":"회차별 교육 내역","columns":[{"key":"date","label":"일자","type":"date","required":false,"max":500},{"key":"startTime","label":"시작시간","type":"time","required":false,"max":500},{"key":"endTime","label":"종료시간","type":"time","required":false,"max":500},{"key":"topic","label":"강의주제 및 내용","type":"text","required":false,"max":500},{"key":"instructor","label":"주강사명","type":"text","required":false,"max":500},{"key":"hours","label":"주강사 교육시간","type":"number","required":false,"max":12},{"key":"assistant","label":"보조강사명","type":"text","required":false,"max":500},{"key":"assistantHours","label":"보조강사 교육시간","type":"number","required":false,"max":12},{"key":"location","label":"교육장소","type":"text","required":false,"max":500}],"min":1,"max":60}]}}$schema$::jsonb->k$fn$;

create or replace function life_private.operation_field(value jsonb, spec jsonb) returns boolean language plpgsql immutable set search_path='' as $$
declare s text;begin
 if jsonb_typeof(value) is distinct from 'string' then return false;end if;
 s:=value#>>'{}';if length(s)>(spec->>'max')::integer then return false;end if;
 if s='' then return true;end if;
 if spec->>'type'='number' then return s~'^\d{1,9}(\.\d{1,2})?$' and (spec->>'key' not in ('ratio','satisfaction') or s::numeric<=100);end if;
 if spec->>'type'='date' then return s~'^\d{4}-\d{2}-\d{2}$' and to_char(s::date,'YYYY-MM-DD')=s;end if;
 if spec->>'type'='time' then return s~'^([01]\d|2[0-3]):[0-5]\d$';end if;
 return true;
 exception when others then return false;
end$$;

create or replace function life_private.operation_content_valid(c jsonb,k text,complete boolean default false) returns boolean language plpgsql immutable set search_path='' as $$
declare spec jsonb; x jsonb; t jsonb; r jsonb; col jsonb; ff jsonb; tt jsonb; source_sig jsonb;begin
 if k is null or k not in ('plan','result') or jsonb_typeof(c) is distinct from 'object' or octet_length(c::text)>3000000 then return false;end if;
 if (select count(*) from jsonb_object_keys(c)) not in (4,5) or not c ?& array['fields','tables','photos','signature'] or jsonb_typeof(c->'fields') is distinct from 'object' or jsonb_typeof(c->'tables') is distinct from 'object' or jsonb_typeof(c->'photos') is distinct from 'array' then return false;end if;
 if (select count(*) from jsonb_object_keys(c))=5 and (k<>'result' or not c ? 'sourceSignature') then return false;end if;
 source_sig:=c->'sourceSignature';
 if source_sig is not null and (jsonb_typeof(source_sig) is distinct from 'object' or (select count(*) from jsonb_object_keys(source_sig))<>3 or not source_sig ?& array['image','page','fileId'] or not life_private.operation_image(source_sig->'image',200000) or source_sig->>'image'='' or jsonb_typeof(source_sig->'page') is distinct from 'number' or (source_sig->>'page')::numeric<>trunc((source_sig->>'page')::numeric) or (source_sig->>'page')::integer not between 1 and 50 or (source_sig->>'fileId') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$') then return false;end if;
 spec:=life_private.operation_schema(k);ff:=spec->'fields';tt:=spec->'tables';
 if (select count(*) from jsonb_object_keys(c->'fields'))<>jsonb_array_length(ff) or (select count(*) from jsonb_object_keys(c->'tables'))<>jsonb_array_length(tt) then return false;end if;
 for x in select * from jsonb_array_elements(ff) loop
  if not life_private.operation_field(c->'fields'->(x->>'key'),x) or (complete and coalesce((x->>'required')::boolean,false) and btrim(c->'fields'->>(x->>'key'))='') then return false;end if;
 end loop;
 if c->'fields'->>'startsOn'<>'' and c->'fields'->>'endsOn'<>'' and c->'fields'->>'startsOn'>c->'fields'->>'endsOn' then return false;end if;
 for t in select * from jsonb_array_elements(tt) loop
  if jsonb_typeof(c->'tables'->(t->>'key')) is distinct from 'array' or jsonb_array_length(c->'tables'->(t->>'key'))>(t->>'max')::integer or (complete and jsonb_array_length(c->'tables'->(t->>'key'))<coalesce((t->>'min')::integer,0)) then return false;end if;
  for r in select * from jsonb_array_elements(c->'tables'->(t->>'key')) loop
   if jsonb_typeof(r) is distinct from 'object' or (select count(*) from jsonb_object_keys(r))<>jsonb_array_length(t->'columns') then return false;end if;
   for col in select * from jsonb_array_elements(t->'columns') loop
    if not life_private.operation_field(r->(col->>'key'),col) then return false;end if;
   end loop;
   if t->>'key'='schedule' and r->>'startTime'<>'' and r->>'endTime'<>'' and r->>'startTime'>=r->>'endTime' then return false;end if;
   if complete and t->>'key'='schedule' and (btrim(r->>'date')='' or btrim(r->>'startTime')='' or btrim(r->>'endTime')='' or btrim(r->>'topic')='' or btrim(r->>'instructor')='' or r->>'hours'='' or btrim(r->>'location')='') then return false;end if;
   if complete and t->>'key'='instructors' and btrim(r->>'name')='' then return false;end if;
  end loop;
 end loop;
 if (case when k='result' then jsonb_array_length(c->'photos') not between 2 and 32 else jsonb_array_length(c->'photos')<>0 end) or not life_private.operation_image(c->'signature',200000) then return false;end if;
 for r in select * from jsonb_array_elements(c->'photos') loop
  if jsonb_typeof(r) is distinct from 'object' or (select count(*) from jsonb_object_keys(r))<>3 or not r ?& array['caption','date','image'] or not life_private.operation_field(r->'caption','{"type":"text","max":100}'::jsonb) or not life_private.operation_field(r->'date','{"type":"date","max":10}'::jsonb) or not life_private.operation_image(r->'image',400000) then return false;end if;
 end loop;
 return true;exception when others then return false;
end$$;

do $$begin
 if exists(select 1 from public.life_operation_documents where not life_private.operation_content_valid(content,kind)) then raise exception 'OPERATION_SCHEDULE_MIGRATION_INVALID';end if;
end$$;

drop function life_private.operation_schedule_row_v2(jsonb);

commit;
